ay_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/10/35/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/10/35/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/10/35/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/10/\",\"title\":\"Chapter Ten: The Opulence of the Absolute\"}],\"url_path\":\"/en/library/bg/10/35/\",\"bb\":2714,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/10/34/\",\"title\":\"TEXT 34\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/10/36/\",\"title\":\"TEXT 36\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3070,\"bb\":568274,\"url_path\":\"/en/library/bg/10/35/devanagari/\",\"body_final\":\"बृहत्साम तथा साम्न‍ां गायत्री छन्दसामहम् ।
मासानां मार्गशीर्षोऽहमृतूनां कुसुमाकर: ॥ ३५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3071,\"bb\":2715,\"url_path\":\"/en/library/bg/10/35/b2715/\",\"body_value\":\"bṛhat-sāma tathā sāmnāṁ
gāyatrī chandasām aham
māsānāṁ mārga-śīrṣo ’ham
ṛtūnāṁ kusumākaraḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3072,\"bb\":2716,\"url_path\":\"/en/library/bg/10/35/b2716/\",\"shadow_value\":\"bṛhat-sāma – the Bṛhat-sāma; tathā – also; sāmnām – of the Sāma Veda songs; gāyatrī – the Gāyatrī hymns; chandasām – of all poetry; aham – I am; māsānām – of months; mārga-śīrṣaḥ – the month of November-December; aham – I am; ṛtūnām – of all seasons; kusuma-ākaraḥ – spring.\",\"word_for_word_value\":[{\"word\":\"bṛhat-sāma\",\"translation\":\"the Bṛhat-sāma\"},{\"word\":\"tathā\",\"translation\":\"also\"},{\"word\":\"sāmnām\",\"translation\":\"of the Sāma Veda songs\"},{\"word\":\"gāyatrī\",\"translation\":\"the Gāyatrī hymns\"},{\"word\":\"chandasām\",\"translation\":\"of all poetry\"},{\"word\":\"aham\",\"translation\":\"I am\"},{\"word\":\"māsānām\",\"translation\":\"of months\"},{\"word\":\"mārga-śīrṣaḥ\",\"translation\":\"the month of November-December\"},{\"word\":\"aham\",\"translation\":\"I am\"},{\"word\":\"ṛtūnām\",\"translation\":\"of all seasons\"},{\"word\":\"kusuma-ākaraḥ\",\"translation\":\"spring\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3073,\"bb\":2717,\"url_path\":\"/en/library/bg/10/35/b2717/\",\"body_value\":\"Of the hymns in the Sāma Veda I am the Bṛhat-sāma, and of poetry I am the Gāyatrī. Of months I am Mārgaśīrṣa [November-December], and of seasons I am flower-bearing spring.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3074,\"bb\":2718,\"url_path\":\"/en/library/bg/10/35/b2718/\",\"body_value\":\"It has already been explained by the Lord that amongst all the Vedas, He is the Sāma Veda. The Sāma Veda is rich with beautiful songs played by the various demigods. One of these songs is the Bṛhat-sāma, which has an exquisite melody and is sung at midnight.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3075,\"bb\":2719,\"url_path\":\"/en/library/bg/10/35/b2719/\",\"body_value\":\"In Sanskrit, there are definite rules that regulate poetry; rhyme and meter are not written whimsically, as in much modern poetry. Amongst the regulated poetry, the Gāyatrī mantra, which is chanted by the duly qualified brāhmaṇas, is the most prominent. The Gāyatrī mantra is mentioned in the Śrīmad-Bhāgavatam. Because the Gāyatrī mantra is especially meant for God realization, it represents the Supreme Lord. This mantra is meant for spiritually advanced people, and when one attains success in chanting it, he can enter into the transcendental position of the Lord. One must first acquire the qualities of the perfectly situated person, the qualities of goodness according to the laws of material nature, in order to chant the Gāyatrī mantra. The Gāyatrī mantra is very important in Vedic civilization and is considered to be the sound incarnation of Brahman. Brahmā is its initiator, and it is passed down from him in disciplic succession.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3076,\"bb\":2720,\"url_path\":\"/en/library/bg/10/35/b2720/\",\"body_value\":\" The month of November-December is considered the best of all months because in India grains are collected from the fields at this time and the people become very happy. Of course spring is a season universally liked because it is neither too hot nor too cold and the flowers and trees blossom and flourish. In spring there are also many ceremonies commemorating Kṛṣṇa’s pastimes; therefore this is considered to be the most joyful of all seasons, and it is the representative of the Supreme Lord, Kṛṣṇa.\"}]}],\"short_title\":\"Bg. 10.35\",\"medium_title\":\"Bhagavad-gītā As It Is 10.35\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.pus