ay_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/10/36/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/10/36/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/10/36/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/10/\",\"title\":\"Chapter Ten: The Opulence of the Absolute\"}],\"url_path\":\"/en/library/bg/10/36/\",\"bb\":2721,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/10/35/\",\"title\":\"TEXT 35\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/10/37/\",\"title\":\"TEXT 37\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3078,\"bb\":568275,\"url_path\":\"/en/library/bg/10/36/devanagari/\",\"body_final\":\"द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम् ।
जयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम् ॥ ३६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3079,\"bb\":2722,\"url_path\":\"/en/library/bg/10/36/b2722/\",\"body_value\":\"dyūtaṁ chalayatām asmi
tejas tejasvinām aham
jayo ’smi vyavasāyo ’smi
sattvaṁ sattvavatām aham\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3080,\"bb\":2723,\"url_path\":\"/en/library/bg/10/36/b2723/\",\"shadow_value\":\"dyūtam – gambling; chalayatām – of all cheats; asmi – I am; tejaḥ – the splendor; tejasvinām – of everything splendid; aham – I am; jayaḥ – victory; asmi – I am; vyavasāyaḥ – enterprise or adventure; asmi – I am; sattvam – the strength; sattva-vatām – of the strong; aham – I am.\",\"word_for_word_value\":[{\"word\":\"dyūtam\",\"translation\":\"gambling\"},{\"word\":\"chalayatām\",\"translation\":\"of all cheats\"},{\"word\":\"asmi\",\"translation\":\"I am\"},{\"word\":\"tejaḥ\",\"translation\":\"the splendor\"},{\"word\":\"tejasvinām\",\"translation\":\"of everything splendid\"},{\"word\":\"aham\",\"translation\":\"I am\"},{\"word\":\"jayaḥ\",\"translation\":\"victory\"},{\"word\":\"asmi\",\"translation\":\"I am\"},{\"word\":\"vyavasāyaḥ\",\"translation\":\"enterprise or adventure\"},{\"word\":\"asmi\",\"translation\":\"I am\"},{\"word\":\"sattvam\",\"translation\":\"the strength\"},{\"word\":\"sattva-vatām\",\"translation\":\"of the strong\"},{\"word\":\"aham\",\"translation\":\"I am\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3081,\"bb\":2724,\"url_path\":\"/en/library/bg/10/36/b2724/\",\"body_value\":\"I am also the gambling of cheats, and of the splendid I am the splendor. I am victory, I am adventure, and I am the strength of the strong.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3082,\"bb\":2725,\"url_path\":\"/en/library/bg/10/36/b2725/\",\"body_value\":\"There are many kinds of cheaters all over the universe. Of all cheating processes, gambling stands supreme and therefore represents Kṛṣṇa. As the Supreme, Kṛṣṇa can be more deceitful than any mere man. If Kṛṣṇa chooses to deceive a person, no one can surpass Him in His deceit. His greatness is not simply one-sided – it is all-sided.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3083,\"bb\":2726,\"url_path\":\"/en/library/bg/10/36/b2726/\",\"body_value\":\" Among the victorious, He is victory. He is the splendor of the splendid. Among the enterprising and industrious, He is the most enterprising, the most industrious. Among adventurers He is the most adventurous, and among the strong He is the strongest. When Kṛṣṇa was present on earth, no one could surpass Him in strength. Even in His childhood He lifted Govardhana Hill. No one can surpass Him in cheating, no one can surpass Him in splendor, no one can surpass Him in victory, no one can surpass Him in enterprise, and no one can surpass Him in strength.\"}]}],\"short_title\":\"Bg. 10.36\",\"medium_title\":\"Bhagavad-gītā As It Is 10.36\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\"